func ScanShortfall(offered, kept int, subject string) error {
	if kept >= offered {
		return nil
	}
	return fmt.Errorf("%s: kept %d of %d rows the cursor yielded (%d lost to scan failures) — refusing the partial result: a silently thinned scan ships an artefact that looks freshly built (bugs_open/410)", subject, kept, offered, offered-kept)
}

